const cleanNipKey = (val) => String(val || '').replace(/\D/g, '').trim()

export const JADWAL_WAWANCARA_BY_NIP = new Map()
export const JADWAL_WAWANCARA_BY_NAME = new Map()

JADWAL_WAWANCARA_1057_REVISI.forEach(item => {
  const cleaned = cleanNipKey(item.nip)
  if (cleaned) {
    JADWAL_WAWANCARA_BY_NIP.set(cleaned, item)
    const unpadded = cleaned.replace(/^0+/, '')
    if (unpadded && unpadded !== cleaned) {
      JADWAL_WAWANCARA_BY_NIP.set(unpadded, item)
    }
  }
  if (item.nama) {
    JADWAL_WAWANCARA_BY_NAME.set(item.nama.trim().toLowerCase(), item)
  }
})

export function lookupJadwalWawancara1057(nipOrNik, nama = '') {
  if (nipOrNik) {
    const key = cleanNipKey(nipOrNik)
    if (JADWAL_WAWANCARA_BY_NIP.has(key)) {
      return JADWAL_WAWANCARA_BY_NIP.get(key)
    }
    const unpadded = key.replace(/^0+/, '')
    if (unpadded && JADWAL_WAWANCARA_BY_NIP.has(unpadded)) {
      return JADWAL_WAWANCARA_BY_NIP.get(unpadded)
    }
  }
  if (nama) {
    const cleanName = nama.trim().toLowerCase()
    if (JADWAL_WAWANCARA_BY_NAME.has(cleanName)) {
      return JADWAL_WAWANCARA_BY_NAME.get(cleanName)
    }
  }
  return null
}

export function formatJadwal1057SessionJam(entryOrSlot, options = {}) {
  const scope = options.scope || 'session_window'
  const morningTime = options.morningTime || '08.30–12.00 WIB'
  const afternoonTime = options.afternoonTime || '13.00–16.30 WIB'
  const backupTime = options.backupTime || '16.30–17.00 WIB'

  if (!entryOrSlot) return morningTime

  const rawSesi = entryOrSlot.sesi || (entryOrSlot.sesiName?.includes('Pagi') ? 'Pagi' : (entryOrSlot.sesiName?.includes('Siang') ? 'Siang' : entryOrSlot.sesiName)) || 'Pagi'
  const sesi = rawSesi.includes('Pagi') ? 'Pagi' : (rawSesi.includes('Siang') ? 'Siang' : rawSesi)
  const isPagi = sesi.toLowerCase().includes('pagi')
  const isSiang = sesi.toLowerCase().includes('siang')

  const baseWindowTime = isPagi ? morningTime : (isSiang ? afternoonTime : backupTime)
  const room = entryOrSlot.room || ''
  const roomDetail = room ? `${sesi} · ${room}` : sesi

  if (scope === 'slot_detail') {
    const rawMicroSlot = entryOrSlot.jam || baseWindowTime
    return roomDetail ? `${rawMicroSlot} (${roomDetail})` : rawMicroSlot
  }

  if (scope === 'time_only') return baseWindowTime

  return roomDetail ? `${baseWindowTime} (${roomDetail})` : baseWindowTime
}
